function drawScore(){if(!lastState)return;$('scoreRows').replaceChildren();for(const p of [...lastState.players].sort((a,b)=>a.team.localeCompare(b.team)||b.kills-a.kills)){const tr=document.createElement('tr');for(const v of [p.name+(p.id===myId?' (sen)':''),p.kills,p.deaths,p.bot?(p.role||'BOT'):p.ping+' ms']){const td=document.createElement('td');td.textContent=v;tr.append(td)}tr.firstChild.style.color=p.team==='blue'?'#60bbef':'#f39b63';$('scoreRows').append(tr)}}
