$('settingsButton').onclick=()=>$('settingsDialog').showModal();for(const id of ['sensitivity','volume','fov','quality']){$(id).value=prefs[id];$(id).oninput=()=>{prefs[id]=id==='quality'?$(id).value:Number($(id).value);safeStorage.set('s16.'+id,prefs[id]);if(id==='sensitivity')$('sensitivityValue').textContent=prefs[id].toFixed(1);if(id==='fov')$('fovValue').textContent=prefs[id];if(id==='quality')updateQuality()}}$('sensitivityValue').textContent=prefs.sensitivity.toFixed(1);$('fovValue').textContent=prefs.fov;
function enterGame(){if(!body)return false;resumePending=false;$('resume').disabled=false;$('resume').textContent='OYUNA DEVAM ET ↗';wakeAudio();if(touchDevice){locked=true;$('pause').hidden=true;touch.reset();if(!window.SECTOR16_CONFIG?.native){document.documentElement.requestFullscreen?.().then(()=>screen.orientation?.lock?.('landscape')).catch(()=>{});}return true}try{const request=$('game').requestPointerLock();request?.catch(()=>toast('Fare kilidi açılamadı. Oyunu ayrı tarayıcı sekmesinde açıp tekrar dene.'))}catch{toast('Bu tarayıcı fare kilidini desteklemiyor. Masaüstü Chrome veya Edge kullan.')}return true}
$('resume').onclick=()=>{if(enterGame())return;resumePending=true;$('resume').disabled=true;$('resume').textContent='OYUN YÜKLENİYOR…';toast('Oyun hazırlanıyor; hazır olduğunda otomatik başlayacak.')};
