for(const button of document.querySelectorAll('[data-team]'))button.onclick=()=>send({type:'team',team:button.dataset.team});
function updateTeamChoices(){if(!lastState||!room)return;for(const team of ['blue','orange']){const players=lastState.players.filter(p=>p.team===team);const humans=players.filter(p=>!p.bot).length;$(team+'Members').textContent=humans+' oyuncu · '+players.filter(p=>p.bot).length+' bot';$('choose'+(team==='blue'?'Blue':'Orange')).disabled=body?.team===team||humans>=Math.ceil(room.maxPlayers/2);}}
$('leave').onclick=()=>{cancelRecovery();send({type:'leave'});resetGame()};$('invite').onclick=async()=>{const link=SERVER_BASE+'/?room='+room.id;try{await navigator.clipboard.writeText(link);toast('Davet bağlantısı kopyalandı. Şifreyi arkadaşına ayrıca ilet.')}catch{toast(link)}};
document.addEventListener('pointerlockchange',()=>{if(touchDevice)return;locked=document.pointerLockElement===$('game');if(room){$('pause').hidden=locked;if(!locked){$('pauseTitle').textContent='Mücadele devam ediyor.';$('pauseText').textContent='Çevrimiçi maç menü açıkken de devam eder.';$('resume').textContent='OYUNA DEVAM ET ↗'}}keys.clear();mouse.fire=false;mouse.aim=false;zoomLevel=0});
document.addEventListener('pointerlockerror',()=>toast('Oyunu tarayıcıda açıp OYUNA GİR düğmesine tekrar tıkla.'));
document.addEventListener('mousemove',e=>{if(!locked||touchDevice)return;const sensitivityScale=Math.tan(camera.fov*Math.PI/360)/Math.tan(prefs.fov*Math.PI/360);yaw-=e.movementX*.002*prefs.sensitivity*sensitivityScale;pitch=clamp(pitch-e.movementY*.002*prefs.sensitivity*sensitivityScale,-1.45,1.45)});
document.addEventListener('keydown',e=>{if(!room)return;if(['Tab','Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='Tab'){drawScore();$('scoreboard').hidden=false}if(['KeyG','KeyH','KeyJ'].includes(e.code)&&!e.repeat&&locked&&body?.hp>0){send({type:'grenade',kind:e.code==='KeyH'?'flash':e.code==='KeyJ'?'smoke':'he'});return}if(e.code==='KeyB'&&!e.repeat){e.preventDefault();if($('buyDialog').open)closeShop();else openShop();return}if(!locked)return;keys.add(e.code);if(e.code==='Digit1')selected=body?.primary||body?.secondary||'pistol';if(e.code==='Digit2')selected=body?.secondary||'pistol';if(e.code==='Digit3')selected='knife'});
document.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='Tab')$('scoreboard').hidden=true});window.addEventListener('blur',()=>{keys.clear();mouse.fire=false;mouse.aim=false;zoomLevel=0});
document.addEventListener('mousedown',e=>{if(!locked||touchDevice)return;if(e.button===0)mouse.fire=true;if(e.button===2){zoomLevel=nextZoomLevel(selected,zoomLevel);mouse.aim=zoomLevel>0;sound('bolt');}});document.addEventListener('mouseup',e=>{if(touchDevice)return;if(e.button===0)mouse.fire=false;if(e.button===2&&selected!=='awp'){zoomLevel=0;mouse.aim=false;}});$('game').addEventListener('contextmenu',e=>e.preventDefault());

let shopSignature='';
function openShop(){if(!room||!body?.canBuy){toast('Silah almak için hayatta ve kendi üssünde olmalısın.');return}pauseGame();$('buyDialog').showModal();$('shopMessage').textContent='';shopSignature='';updateShopState(lastState,body)}
function closeShop(){if($('buyDialog').open)$('buyDialog').close();$('resume').click()}
$('buyButton').onclick=openShop;$('closeShop').onclick=closeShop;
function updateShopState(s,own){const rounds=isRoundMode(s.mode);$('buyButton').hidden=false;$('buyButton').disabled=!own.canBuy;$('economy').hidden=false;$('baseHint').textContent=own.canBuy?'ÜSTESİN · B SATIN AL':'SATIN ALMAK İÇİN ÜSSÜNE DÖN';$('cash').textContent='$'+own.money;$('armor').textContent=own.armor||0;
 $('roundInfo').textContent=s.mode==='ctf'?'BAYRAK KAPMACA / HEDEF 5':rounds?'RAUND '+s.round+' · HEDEF '+s.roundTarget:'';
 $('phaseInfo').textContent=s.mode==='ctf'?(s.flags?.[own.team==='blue'?'orange':'blue']?.carrier===myId?'BAYRAK SENDE · ÜSSÜNE DÖN':s.flags?.[own.team]?.carrier?'BAYRAĞINIZ RAKİPTE':'RAKİP BAYRAĞINI ÜSSÜNE GETİR'):rounds?(s.phase==='buy'?(s.remaining>0?'ALIŞVERİŞ · B':'RAKİP BEKLENİYOR'):s.phase==='live'?'ELEME':s.phase==='matchEnd'?'MAÇ BİTTİ':'RAUND BİTTİ'):'';
 $('shopCash').textContent='$'+own.money;$('shopTime').textContent=own.canBuy?'Üste süre sınırı yok':'Üssün dışındasın';
 if(!own.canBuy&&$('buyDialog').open){$('buyDialog').close();toast('Alışveriş kapandı. Hayatta ve kendi üssünde olmalısın.')}
 if(!$('buyDialog').open)return;const signature=[own.money,own.primary,own.secondary,own.armor,own.canBuy].join(':');if(signature===shopSignature)return;shopSignature=signature;$('shopItems').replaceChildren();
 for(const[id,w]of [...Object.entries(WEAPONS).filter(([,w])=>w.slot!=='melee'),['armor',{name:'Kevlar + kask',price:650,slot:'armor'}]]){const owned=id==='armor'?own.armor>=100:id===own.primary||id===own.secondary;const b=document.createElement('button');b.className='shop-item';b.disabled=owned||own.money<w.price||!own.canBuy;const title=document.createElement('b'),desc=document.createElement('span'),price=document.createElement('strong');title.textContent=w.name;desc.textContent=id==='armor'?'100 zırh':(w.slot==='primary'?'ANA SİLAH':'TABANCA')+' · '+w.mag+' mermi';price.textContent=owned?'ENVANTERDE':'$'+w.price;b.append(title,desc,price);b.onclick=()=>send({type:'buy',item:id});$('shopItems').append(b)}
}

