function createNameplate(nickname,team){
 const canvas=document.createElement('canvas');canvas.width=512;canvas.height=96;
 const context=canvas.getContext('2d');const text=String(nickname||'Oyuncu').slice(0,26);
 context.font='600 36px Arial';let size=36;while(context.measureText(text).width>464&&size>20){context.font='600 '+(--size)+'px Arial'}
 const width=Math.min(504,context.measureText(text).width+36),left=(512-width)/2;
 context.fillStyle='rgba(8,17,23,0.82)';context.fillRect(left,14,width,68);
 context.fillStyle=team==='blue'?'#8cd9ff':'#ffbb8d';context.fillRect(left,79,width,3);
 context.textAlign='center';context.textBaseline='middle';context.fillText(text,256,48);
 const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;
 const material=new THREE.SpriteMaterial({map:texture,transparent:true,depthTest:true,depthWrite:false,toneMapped:false});
 const sprite=new THREE.Sprite(material);sprite.position.y=2.16;sprite.scale.set(2.8,.525,1);sprite.userData.nameplate=true;return sprite;
}
function createSoldier(team,nickname,skin='standard'){const g=createOperator(team),tone=SKINS.find(s=>s.id===skin)?.color;if(tone)g.traverse(o=>{if(o.isMesh&&o.material?.color){o.material=o.material.clone();o.material.color.lerp(new THREE.Color(tone),.42)}});const halo=new THREE.Mesh(new THREE.RingGeometry(.50,.53,32),new THREE.MeshBasicMaterial({color:team==='blue'?0x76d5ff:0xffb76d,side:THREE.DoubleSide,transparent:true,opacity:.8}));halo.rotation.x=-Math.PI/2;halo.position.y=.025;g.add(halo);g.userData.halo=halo;const nameplate=createNameplate(nickname,team);g.add(nameplate);g.userData.nameplate=nameplate;return g;}
function shotEffect(m){if(!room)return;if(m.surface)surfaceEffect(m);const profile=shotProfile(m.weapon),points=[new THREE.Vector3(m.from.x,m.from.y,m.from.z),new THREE.Vector3(m.to.x,m.to.y,m.to.z)];const geometry=new THREE.BufferGeometry().setFromPoints(points);const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:m.weapon==='awp'?0xfff1bf:0xffd17c,transparent:true,opacity:m.weapon==='awp'?.92:.6}));addCombatEffect({mesh:line,life:profile.tracer,total:profile.tracer});const spark=new THREE.Mesh(new THREE.SphereGeometry(m.weapon==='awp'?.10:.055,6,4),new THREE.MeshBasicMaterial({color:m.weapon==='awp'?0xffffff:0xffc26c}));spark.position.set(m.to.x,m.to.y,m.to.z);addCombatEffect({mesh:spark,life:m.weapon==='awp'?.20:.12,total:m.weapon==='awp'?.20:.12});if(m.id!==myId){const v=remote.get(m.id);if(v)v.shot=1;sound('shot',m.from,m.weapon,m.suppressed);}}
function disposeEffect(e){scene.remove(e.mesh);e.mesh.traverse(o=>{o.geometry?.dispose();if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();});}
function clearEffects(){for(const e of effects)disposeEffect(e);effects.length=0;}
function addCombatEffect(e){while(effects.length>=160)disposeEffect(effects.shift());scene.add(e.mesh);effects.push(e);}
function surfaceEffect(m){
 const n=new THREE.Vector3(m.surface.normal.x,m.surface.normal.y,m.surface.normal.z),at=new THREE.Vector3(m.to.x,m.to.y,m.to.z).addScaledVector(n,.012);
 const mark=new THREE.Mesh(new THREE.CircleGeometry(m.weapon==='awp'?.085:.045,8),new THREE.MeshBasicMaterial({color:0x182126,transparent:true,opacity:.85,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2}));mark.position.copy(at);mark.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),n);
 addCombatEffect({mesh:mark,life:10,total:10,update(dt,e){mark.material.opacity=Math.min(.85,e.life/2)}});
 for(let i=0;i<(prefs.quality==='low'?2:5);i++){const mesh=new THREE.Mesh(new THREE.BoxGeometry(.025,.025,.025),new THREE.MeshBasicMaterial({color:m.surface.metal?0xffd780:0xa9aaa1,transparent:true}));mesh.position.copy(at);const v=n.clone().multiplyScalar(1+Math.random()*2).add(new THREE.Vector3(Math.random()-.5,Math.random(),Math.random()-.5));addCombatEffect({mesh,life:.25,total:.25,update(dt,e){v.y-=7*dt;mesh.position.addScaledVector(v,dt);mesh.material.opacity=e.life/e.total}});}
}
function impactEffect(m){
 if(!room)return;const visual=remote.get(m.victimId);if(visual)visual.hit=1;
 const count=prefs.quality==='low'?4:8;
 for(let i=0;i<count;i++){
  const mesh=new THREE.Mesh(new THREE.BoxGeometry(.035,.035,.035),new THREE.MeshBasicMaterial({color:m.armor?0x9ae4ff:m.head?0xffdb85:0xd0b49a,transparent:true}));
  mesh.position.set(m.position.x,m.position.y,m.position.z);
  const velocity=new THREE.Vector3((Math.random()-.5)*2-m.direction.x,(Math.random()*2)+.5,(Math.random()-.5)*2-m.direction.z);
  addCombatEffect({mesh,life:.28,total:.28,update(dt,e){velocity.y-=5*dt;mesh.position.addScaledVector(velocity,dt);mesh.material.opacity=e.life/e.total;}});
 }
}
function deathEffect(m){
 if(!room||!m.victimId||!m.position)return;
 const key=m.victimId+':'+m.generation;if(deathEvents.has(key))return;deathEvents.add(key);if(deathEvents.size>64)deathEvents.delete(deathEvents.values().next().value);
 const visual=remote.get(m.victimId);if(visual)visual.group.visible=false;
 if(m.victimId===myId){deathTime=.01;mouse.fire=false;mouse.aim=false;return;}
 if(!visual)return;
 // Separate geometry/material ownership lets a respawn reuse the live soldier safely.
 const mesh=new THREE.Group();for(const part of visual.group.children){if(part.isSprite||part===visual.group.userData.halo)continue;const clone=part.clone(true);clone.traverse(o=>{if(o.isMesh){o.geometry=o.geometry.clone();o.material=o.material.clone();o.material.transparent=true;}});mesh.add(clone);}
 mesh.position.set(m.position.x,m.position.y,m.position.z);mesh.rotation.y=m.yaw;mesh.scale.y=1;
 const baseY=m.position.y;
 addCombatEffect({mesh,life:1.7,total:1.7,update(dt,e){const age=e.total-e.life,t=Math.min(1,age/.55),fall=t*t*(3-2*t);mesh.rotation.x=fall*Math.PI/2;mesh.position.y=baseY+.13*fall;mesh.position.x+=m.direction.x*dt*(1-t)*1.1;mesh.position.z+=m.direction.z*dt*(1-t)*1.1;mesh.traverse(part=>{if(part.isMesh)part.material.opacity=Math.min(1,e.life/.55);});}});
}
function explosionEffect(m){if(!room)return;sound('explosion',m.position);const position=new THREE.Vector3(m.position.x,m.position.y,m.position.z);if(body&&position.distanceTo(camera.position)<12)damageKick=1;
 const sphere=new THREE.Mesh(new THREE.SphereGeometry(.3,12,8),new THREE.MeshBasicMaterial({color:0xffaa46,transparent:true,depthWrite:false}));sphere.position.copy(position);addCombatEffect({mesh:sphere,life:.3,total:.3,update(dt,e){sphere.scale.addScalar(dt*14);sphere.material.opacity=e.life/e.total;}});
 for(let i=0;i<(prefs.quality==='low'?7:16);i++){const smoke=new THREE.Mesh(new THREE.SphereGeometry(.22,7,5),new THREE.MeshBasicMaterial({color:i%3?0x746d60:0xcaa675,transparent:true,depthWrite:false}));smoke.position.copy(position);const v=new THREE.Vector3((Math.random()-.5)*5,Math.random()*3+1,(Math.random()-.5)*5);addCombatEffect({mesh:smoke,life:1.3,total:1.3,update(dt,e){smoke.position.addScaledVector(v,dt);smoke.scale.addScalar(dt*1.7);smoke.material.opacity=e.life/e.total*.45;}});}
}
function updateObjectiveHUD(now){const b=lastState?.bomb;$('objective').hidden=lastState?.mode!=='bomb';if(!b)return;const time=lastState.time+(now-stateReceivedAt)/1000;let text='',progress=0;
 if(b.state==='planted'){text='BOMBA KURULDU · '+Math.max(0,Math.ceil(b.detonateAt-time))+' sn';if(body.team==='blue'&&body.hp>0&&Math.hypot(body.x-b.x,body.z-b.z)<2)text+=' · E BASILI TUT: İMHA';if(b.defuseBy){progress=(time-b.defuseStart)/DEFUSE_SECONDS;text=b.defuseBy===myId?'İMHA EDİLİYOR · E BASILI TUT':'BOMBA İMHA EDİLİYOR';}if(now-lastBombBeep>Math.max(220,(b.detonateAt-time)*30)){sound('hit',{x:b.x,z:b.z});lastBombBeep=now;}}
 else if(b.carrier===myId){const atSite=bombSites(room.map).some(site=>Math.hypot(body.x-site.x,body.z-site.z)<site.radius);text=atSite?'E BASILI TUT: BOMBA KUR':'BOMBA SENDE · A VEYA B ALANINA GİT';if(b.plantBy===myId){text='KURULUYOR · HAREKET ETME / E BASILI TUT';progress=(time-b.plantStart)/PLANT_SECONDS;}}
 else text=b.state==='dropped'?(body.team==='orange'?'DÜŞEN BOMBAYI AL':'DÜŞEN BOMBAYI KORU'):body.team==='blue'?'A / B ALANLARINI SAVUN':'BOMBA TAŞIYICISINI KORU';
 $('objectiveText').textContent=text;$('objectiveProgress').style.width=clamp(progress,0,1)*100+'%';
}
